#!/usr/bin/env python3
"""
Round 215o (culprits), 16 October 2026. Needs round 214o.

Every gravity and anti-gravity heading and layer taken out, with the From
Earth view they opened.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 215o (16 October)\n\nNeeds round 214o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Every gravity and anti-gravity heading and layer taken out (asked 16\n  October): earth_pull_in, earth_pull_out, antigravity, gravity_fields; the\n  To Earth heading "Earth\'s gravity reach" and the Antigravity sub-heading\n  under the space industry; map/data/antigravity.geojson deleted.\n- bodies.html: the From Earth view (earthreach) and its code (gravity\'s\n  fabric, gravity reaching Earth) taken out. Sunlight\'s reach, the Sky, Sun,\n  Moon and Mars views are unchanged. The tiles repo\'s reach/masses.json is no\n  longer read by the map (reach.py still writes it; harmless).\n- Not done: the South America "homicides against tribes" picture. It has no\n  source, legend or licence, and its dark marks cannot be told apart from\n  dark forest; the link it came with was an INPE fires download. Waiting on\n  the data file or its source.\n\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round215o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 214o" not in h.read_text(encoding="utf-8"):
        sys.exit("round215o: round 214o must be applied first (round214o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round215o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/bodies.html", "map/test.mjs", "map/data/antigravity.geojson", check=False)
            sys.exit("round215o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round215o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
